-- ============================================================================================
-- CVM_CATEGORY_FIXES — правки справочника категорий CVM данными (19.10.2026, после выкладки справочника).
-- Запустить целиком в SSMS (F5). Повторный запуск безопасен: результат тот же.
--
-- Действия по объектам:
--   dbo.I_CVM_CATEGORY                — добавляются 25 новых полок (ID 1659–1683);
--                                       переименовываются 6; «без шкалы» меняется у 1;
--                                       закрываются (STATUS 0, DATE_CLOSE) 2 пустых: 1350, 1556.
--   dbo.I_CVM_CATEGORY_MAP            — у 76 кодов ДИКСИ меняется привязка (код целиком → новая полка
--                                       или код режется правилами слов).
--   dbo.I_CVM_CATEGORY_RULE           — правила 72 кодов пересобираются (удаляются и вставляются заново
--                                       только у этих кодов).
--   dbo.I_CVM_PRODUCT_CATEGORY_MANUAL — 3126 товаров поштучно (новые строки или новая полка у старых).
--   dbo.cvm_category_refresh          — новая версия (create or alter): новые коды ДИКСИ привязываются каждый день
--                                       сразу после загрузки I_PRODUCT — по прежней категории их товаров
--                                       (перекодировка ДИКСИ), иначе по соседним кодам того же родителя
--                                       (≥ 2 соседа, все в одной полке); остальное — «несопоставлен», как раньше.
--   dbo.I_CVM_PRODUCT_CATEGORY        — пересчитывается процедурой: меняется полка у 3808 товаров.
--   Ничего не удаляется, кроме правил пересобираемых кодов; ID не перевыдаются; задание MCI не меняется.
-- ============================================================================================

use mci_model;
go
set noexec off;
set nocount on;
set xact_abort on;
go

-- 0. Не во время «MCI Regular update»: скрипт пересоздаёт процедуру его шага CVM_CATEGORY и запускает её —
--    параллельный прогон даст конфликт ключей и чтение I_PRODUCT во время перезаливки. Иначе — стоп, ничего не изменено.
exec sys.sp_set_session_context @key = N'cvm_fixes_ok', @value = 0;
if exists (select 1 from msdb.dbo.sysjobactivity as a (nolock)
           join msdb.dbo.sysjobs as j (nolock) on j.job_id = a.job_id
           where j.name = N'MCI Regular update' and a.start_execution_date is not null and a.stop_execution_date is null
             and a.session_id = (select max(session_id) from msdb.dbo.syssessions (nolock)))
begin
    raiserror(N'СТОП: идёт «MCI Regular update» — запустите скрипт после его окончания, ничего не изменено.', 16, 1);
    set noexec on;
end;
go

-- 0а. Новые ID свободны или уже заняты этими же полками (повторный запуск)
if exists (select 1 from dbo.I_CVM_CATEGORY as c (nolock)
           join (values (1659, N'Снеки из нори и морской капусты'), (1660, N'Квас сухой и квасное сусло'), (1661, N'Напитки растворимые'), (1662, N'Уксусная кислота'), (1663, N'Сахарозаменители в таблетках'), (1664, N'Супы консервированные'), (1665, N'Растительные йогурты питьевые'), (1666, N'Масло и спреды шоколадные'), (1667, N'Сырные продукты рассольные'), (1668, N'Хе и корейские закуски из мяса и рыбы'), (1669, N'Мороженое в брикетах'), (1670, N'Фрукты резаные'), (1671, N'Птица копчёная на кости'), (1672, N'Порошки для посудомоечных машин'), (1673, N'Средства от моли'), (1674, N'Сетки, мухобойки и ловушки'), (1675, N'Ароматизаторы для дома'), (1676, N'Губки и щётки для обуви'), (1677, N'Аптечки, таблетницы и контейнеры'), (1678, N'Кофейные наборы'), (1679, N'Винные напитки газированные'), (1680, N'Мясо и шашлык гриль'), (1681, N'Круассаны свежие'), (1682, N'Уценённые товары'), (1683, N'Подарочные наборы алкоголя')) as v (ID, NAME) on v.ID = c.ID_CVM_CATEGORY
           where c.NAME <> v.NAME)
begin
    raiserror(N'СТОП: ID новых полок заняты другими категориями — ничего не изменено.', 16, 1);
    set noexec on;
end;
go

begin transaction;

